import type { AdminLocation } from "@/data/types";

const verifiedAt = "2026-10-09";

function division(id: string, name: string, slug: string, districtId: string, sourceUrl: string): AdminLocation {
  return {
    id,
    name,
    slug,
    type: "revenue-division",
    parentId: districtId,
    districtId,
    mandalId: null,
    aliases: [],
    languageNames: {},
    sourceUrl,
    verifiedAt,
    active: true,
    serviceAvailable: false,
    indexable: false,
    contentQualityStatus: "administrative-record",
  };
}

function mandal(input: {
  divisionId: string;
  districtId: string;
  name: string;
  slug: string;
  sourceUrl: string;
  aliases?: string[];
}): AdminLocation {
  return {
    id: `mandal-${input.districtId.replace("district-", "")}-${input.slug}`,
    name: input.name,
    slug: input.slug,
    type: "mandal",
    parentId: input.divisionId,
    districtId: input.districtId,
    mandalId: `mandal-${input.districtId.replace("district-", "")}-${input.slug}`,
    aliases: input.aliases ?? [],
    languageNames: {},
    sourceUrl: input.sourceUrl,
    verifiedAt,
    active: true,
    serviceAvailable: false,
    indexable: false,
    contentQualityStatus: "administrative-record",
  };
}

